script:
frappe
	.require("/assets/payment_core/js/payment_analytics_render.js")
	.then(() => {
		const Renderer = window.PaymentAnalyticsRender;

		// shared report styling, injected into the shadow root (app
		// stylesheets do not reach inside it)
		const style = document.createElement("style");
		style.textContent = Renderer.style();
		root_element.prepend(style);

		const state = { range_key: "30", currency: null, reference_doctype: null };
		let request_seq = 0;

		function q(sel) {
			return root_element.querySelector(sel);
		}

		function fill_select(select, options, value) {
			select.innerHTML = options
				.map((opt) => `<option value="${Renderer.esc(opt.value)}">${Renderer.esc(opt.label)}</option>`)
				.join("");
			select.value = value == null ? "" : value;
			if (select.value !== String(value == null ? "" : value) && options.length) {
				select.selectedIndex = 0;
			}
		}

		function load() {
			const seq = ++request_seq;
			q(".pc-status").textContent = __("Loading") + "...";
			frappe
				.call({
					method: "payment_core.analytics.get_analytics",
					args: {
						range_key: state.range_key,
						currency: state.currency,
						reference_doctype: state.reference_doctype,
					},
				})
				.then((r) => {
					if (seq !== request_seq) return;
					const data = (r && r.message) || {};
					if (data.range) state.range_key = data.range;
					state.currency = data.currency || state.currency;
					state.reference_doctype = data.reference_doctype || null;
					const currencies = (data.currencies || []).map((c) => ({ value: c, label: c }));
					fill_select(
						q("#pc-currency"),
						currencies.length ? currencies : [{ value: "", label: __("No currency") }],
						state.currency || ""
					);
					fill_select(
						q("#pc-doctype"),
						[{ value: "", label: __("All reference types") }].concat(
							(data.doctype_breakdown || []).map((row) => ({
								value: row.doctype,
								label: row.doctype,
							}))
						),
						state.reference_doctype || ""
					);
					q("#pc-range").value = state.range_key;
					Renderer.render(q(".payment-analytics-dashboard"), data, {
						currency: state.currency,
					});
					q(".pc-status").textContent = __("Updated");
				})
				.catch(() => {
					if (seq === request_seq) q(".pc-status").textContent = __("Unable to load");
				});
		}

		q("#pc-range").addEventListener("change", function () {
			state.range_key = this.value;
			load();
		});
		q("#pc-currency").addEventListener("change", function () {
			state.currency = this.value || null;
			load();
		});
		q("#pc-doctype").addEventListener("change", function () {
			state.reference_doctype = this.value || null;
			load();
		});
		q("#pc-refresh").addEventListener("click", load);

		load();
	});

style:
.pc-filters {
	display: flex;
	flex-wrap: wrap;
	align-items: flex-end;
	gap: var(--margin-md);
	padding-bottom: var(--padding-md);
}

.pc-filter {
	display: flex;
	flex-direction: column;
	gap: var(--margin-xs);
}

.pc-filter label {
	color: var(--text-muted);
	font-size: var(--text-xs);
	font-weight: var(--weight-semibold);
	letter-spacing: 0.04em;
	text-transform: uppercase;
}

.pc-filter select {
	min-width: 140px;
	padding: var(--padding-xs) var(--padding-sm);
	border: 1px solid var(--border-color);
	border-radius: var(--border-radius);
	background: var(--control-bg);
	color: var(--text-color);
}

.pc-status {
	font-size: var(--text-sm);
}
